    </div>
    <div class="card" style="margin-bottom:6px;"><div class="flex-row"><label>🌐 FETCH:</label><select id="proxySelect" onchange="UI.onProxyChange()"><option value="direct">⚡ Direct</option><option value="builtin">🔁 Proxy</option><option value="custom">📝 Custom</option></select><input type="text" id="corsProxyUrl" placeholder="Proxy URL" style="display:none;width:180px;"><label>🔐 WALLET:</label><input type="text" id="walletProxyUrl" style="width:140px;"><label>🔗 Exec Path:</label><input type="text" id="execPath" value="/execute" style="width:65px;"><button onclick="UI.logButton('SAVE PROXY');saveProxyConfig()" class="cyan">SAVE</button></div><div id="proxyStatusMsg"></div><div class="flex-row" style="margin-top:4px;"><label>🌐 Testnets:</label><input type="checkbox" id="testnetToggle" onchange="toggleTestnets()"> <span style="font-size:8px;color:#888;">Binance Testnet, OKX Demo, Uniswap Sepolia</span> <label>⏸️ Pause Logs:</label><input type="checkbox" id="pauseLogsToggle" onchange="togglePauseLogs()"></div></div>
