    <div class="flex-row" style="gap:8px;margin:4px 0;"><label>🔍 UI Scale:</label><input type="range" id="uiScaleSlider" min="8" max="16" value="10" oninput="setUIScale(this.value)" style="width:120px;"><span id="uiScaleLabel">10px</span></div>

    <div id="graphSlotContainer"><h3 style="color:var(--gold);">🌐 MULTI‑LINE GRAPH</h3><canvas id="graphNetwork" width="700" height="380"></canvas><div>🟢 Size = purchase power | 🔆 Glow = profit | ⚠️ Dashed red = shared edge</div><div><label>🔗 Depth: <span id="slotDepthLabel2">5</span></label><label><input type="checkbox" id="autoOpenTrade" checked> Auto‑open</label><label><input type="checkbox" id="bellmanToggle" onchange="UI.logButton('Bellman toggle')"> Bellman‑Ford</label><label>🎯 Target: <input type="text" id="targetAssetsInput" placeholder="e.g. BABYDOGE,USDT" style="width:130px;"></label><span class="target-preset" onclick="setTargetPreset('BABYDOGE,MEME,PEPE,WOW,TRON')">🕹️ Meme</span><span class="target-preset" onclick="setTargetPreset('USDT,USDC,USD,GUSD')">💵 Stables</span><span class="target-preset" onclick="setTargetPreset('BTC,ETH,SOL,LINK')">🏦 Blue</span><label>📉 Short: <input type="checkbox" id="shortToggle"></label><label>📊 Min Profit%: <input type="number" id="minProfitInput" value="0.0001" step="0.0001" style="width:60px;"></label><label>🔄 Fallback: <input type="checkbox" id="fallbackCheck" checked></label><label>🌈 Lines: <input type="number" id="multiLineCount" value="7" min="1" max="8" style="width:35px;"></label><label>💰 Reinvest%: <input type="number" id="reinvestPercent" value="50" min="0" max="100" style="width:40px;">%</label><label>📈 Index%: <input type="number" id="indexFundPercent" value="5" min="0" max="25" style="width:35px;">%</label><label>🧠 Smart Order: <input type="checkbox" id="smartBatchToggle" checked></label></div><button onclick="UI.logButton('PULL LEVER');Engine.pullGraphLever()" class="gold" id="pullLeverBtn2">🎰 PULL LEVER <span id="pullCountdown2"></span></button><button onclick="UI.logButton('EXECUTE ALL');Engine.executeAllLines()" class="allin">🚀 EXECUTE ALL LINES</button><div id="slotResult2"></div><div id="accumulationInfo" style="font-size:8px;color:var(--cyan);"></div><div id="batchResult"></div><details><summary style="color:var(--cyan);cursor:pointer;">📜 Batch History</summary><div id="batchHistory"></div></details></div>

