            this.lastCoinCreateTime=s.lastCoinCreateTime||0; this.operationLatency=s.operationLatency||[];
            this.testnetsActive=s.testnetsActive||false; this.apiKeys=s.apiKeys||{}; this.coinLevels=s.coinLevels||{};
            this.royalties=s.royalties||0;
