            customProxyUrl:this.customProxyUrl, basketHoldings:this.basketHoldings,
            batchHistory:this.batchHistory.slice(-20), coinExchangeList:this.coinExchangeList,
            wsReconnects:this.stats.wsReconnects, lastCoinCreateTime:this.lastCoinCreateTime,
            operationLatency:this.operationLatency.slice(-10), testnetsActive:this.testnetsActive,
            apiKeys:this.apiKeys, coinLevels:this.coinLevels, royalties:this.royalties
        }));
        localStorage.setItem('wallet_sol',document.getElementById('solAddress').value);
        localStorage.setItem('wallet_eth',document.getElementById('ethAddress').value);
        localStorage.setItem('basket',document.getElementById('basketInput').value);
        localStorage.setItem('pathDepth',document.getElementById('pathInput').value);
        localStorage.setItem('targetAssets',document.getElementById('targetAssetsInput').value);
    },
    saveWallet(){this.save();},
    addTradeToLedger(opp,size,netProfit){this.tradeLedger.unshift({time:new Date().toISOString(),path:opp.path.join(' → '),size,profit:netProfit,type:opp.type,live:this.liveMode,testnet:this.liveTestMode});if(this.tradeLedger.length>50)this.tradeLedger.length=50;this.save();UI.renderTradeLedger();UI.updateDashboard();},
    addLiveTrade(opp,size,netProfit,txHash){this.liveTradeHistory.unshift({time:new Date().toISOString(),path:opp.path.join(' → '),size,profit:netProfit,txHash});if(this.liveTradeHistory.length>20)this.liveTradeHistory.length=20;this.save();UI.renderLiveTrades();},
    recordBasketPurchase(asset,amount,pathDescription){if(!this.basketHoldings[asset])this.basketHoldings[asset]=0;this.basketHoldings[asset]+=amount;if(!this.acquisitionPaths[asset])this.acquisitionPaths[asset]=[];this.acquisitionPaths[asset].push({amount,path:pathDescription||'unknown',time:new Date().toISOString()});this.save();UI.renderBasketTracker();},
    addBatchHistory(entry){this.batchHistory.unshift(entry);if(this.batchHistory.length>20)this.batchHistory.length=20;this.save();UI.renderBatchHistory();UI.updateDashboard();},
    getAssetPrice(asset){const stable=['USDT','USD','USDC','GUSD'];for(const t of stable){const p=this.allPairs.find(p=>p.base===asset&&p.target===t);if(p)return p.bidPrice||p.price*0.999;}const any=this.allPairs.find(p=>p.base===asset);if(any){let price=any.bidPrice||any.price*0.999;if(!stable.includes(any.target)){const tp=this.getAssetPrice(any.target);if(tp>0)price*=tp;}return price;}return 0;},
    computePurchasePower(){this.purchasePower={};if(this.bankroll<=0)return;const prices={};for(const p of this.allPairs){if(!p.base||!p.target)continue;const ask=p.askPrice||p.price*1.001;if(!prices[p.base]||ask<prices[p.base])prices[p.base]=ask;}for(const[asset,price]of Object.entries(prices))if(price>0)this.purchasePower[asset]=this.bankroll/price;for(const s of['USDT','USD','USDC'])if(!this.purchasePower[s])this.purchasePower[s]=this.bankroll;},
    getTargetAssets(){const raw=document.getElementById('targetAssetsInput')?.value.trim();if(raw)return raw.split(',').map(s=>s.trim().toUpperCase());return document.getElementById('basketInput').value.split(',').map(s=>s.trim().toUpperCase());},
    validateEdge(e){return e&&e.rate>0&&e.rate<1e6&&isFinite(e.rate);},
    validateCycle(edges){let p=1;for(const e of edges){if(!this.validateEdge(e))return false;p*=e.rate;}return p>0.5&&p<100;},
    getMaxCoinExchanges(){return Math.min(1+Math.floor(this.level/3),8);},
    getCoinCooldown(){if(this.level<5)return Infinity;return Math.max(60,300-(this.level-5)*30);},
    getPullCooldown(){if(this.level<=3)return 15000;if(this.level<=6)return 12000;if(this.level<=9)return 9000;return 6000;},
    getLiveScanInterval(){if(this.level<2)return 60000;if(this.level<5)return 45000;if(this.level<8)return 30000;if(this.level<10)return 15000;return 10000;},
    startAutoForex(){if(this.forexInterval)clearInterval(this.forexInterval);if(this.level>=3&&this.selectedFiats.size>0){document.getElementById('forexAutoStatus').textContent='🔄 Auto (5min)';this.forexInterval=setInterval(()=>fetchForexRates(),300000);}else document.getElementById('forexAutoStatus').textContent='';},
    allocateIndexFund(profit){const pct=parseFloat(document.getElementById('indexFundPercent')?.value||5)/100;if(pct<=0||profit<=0||!this.userCoins.length)return;const amount=profit*pct;if(amount<=0||this.bankroll<amount)return;this.bankroll-=amount;const totalWeight=this.userCoins.reduce((s,c)=>s+(this.coinLevels[c.symbol]||1),0);let r=Math.random()*totalWeight;for(const c of this.userCoins){r-=(this.coinLevels[c.symbol]||1);if(r<=0){const price=this.getAssetPrice(c.symbol);if(price>0){const qty=amount/price;this.recordBasketPurchase(c.symbol,qty,'Index Fund');}return;}}},
    addCoinXP(symbol,xp){this.coinLevels[symbol]=(this.coinLevels[symbol]||1)+xp;this.save();UI.renderCoinLevels();}
