// ---- Helper functions (log, fetch, etc) ----
function log(msg,type='info'){const t=new Date().toLocaleTimeString();const el=document.getElementById('logs');if(!el)return;const c=type==='error'?'#ff4444':type==='success'?'var(--green)':'inherit';const entry=`<div style="color:${c}">[${t}] ${msg}</div>`;if(State.pauseLogs){State.logBuffer.push(entry);if(State.logBuffer.length>50)State.logBuffer.shift();}else{while(State.logBuffer.length)el.innerHTML=State.logBuffer.shift()+el.innerHTML;el.innerHTML=entry+el.innerHTML;}}
function toggleLogs(){const e=document.getElementById('logs');e.style.display=e.style.display==='none'?'block':'none';}
function toggleSection(id){const e=document.getElementById(id);e.style.display=e.style.display==='none'?'block':'none';}
function updateStatus(m){document.getElementById('mainStatus').textContent=m;}
function toggleTestnets(){State.testnetsActive=document.getElementById('testnetToggle').checked;rebuildExchangeDefinitions();State.save();log(`Testnets: ${State.testnetsActive?'ON':'OFF'}`);}
let logsPaused=false; function togglePauseLogs(){logsPaused=document.getElementById('pauseLogsToggle').checked;log(`Pause Logs: ${logsPaused?'ON':'OFF'}`);}
const BUILTIN_PROXIES=['https://corsproxy.io/?','https://api.allorigins.win/raw?url=']; let currentProxyIndex=0;
function getEffectiveProxyUrl(){if(State.proxyMode==='custom'){const c=document.getElementById('corsProxyUrl').value.trim();if(c&&!c.includes('placeholder'))return c;return null;}if(State.proxyMode==='builtin')return BUILTIN_PROXIES[currentProxyIndex];return null;}
function rotateProxy(){currentProxyIndex=(currentProxyIndex+1)%BUILTIN_PROXIES.length;UI.updateProxyStatus();}
async function smartFetch(url,options={},isCorsSafe=false){if(isCorsSafe||State.proxyMode==='direct'){try{const r=await fetch(url,options);if(r.ok)return r;}catch(e){}}const proxy=getEffectiveProxyUrl();if(proxy){try{const r=await fetch(proxy+encodeURIComponent(url),options);if(!r.ok)throw new Error();const text=await r.text();try{return new Response(JSON.stringify(JSON.parse(text)),{status:200,headers:{'Content-Type':'application/json'}});}catch{return new Response(text,{status:200});}}catch(e){rotateProxy();}}throw new Error('Fetch failed');}
const KNOWN_QUOTES=['USDT','USDC','BUSD','GUSD','USD','BTC','ETH','SOL','EUR','GBP','JPY','KRW','RUB','INR','TRY']; KNOWN_QUOTES.sort((a,b)=>b.length-a.length);
function parsePairSymbol(sym){const s=(sym||'').toUpperCase().replace(/[^A-Z0-9]/g,'');if(!s)return null;for(const q of KNOWN_QUOTES){if(s.endsWith(q)&&s.length>q.length){const b=s.slice(0,s.length-q.length);if(b&&b!==q)return{base:b,target:q};}}const p=s.split(/[_-]/);if(p.length>=2)return{base:p[0],target:p.slice(1).join('_')};return null;}
const exchangeDefs=[{key:'okx',name:'OKX',url:'https://www.okx.com/api/v5/market/tickers?instType=SPOT',parser:'okx'},{key:'binance',name:'Binance',url:'https://api.binance.com/api/v3/ticker/24hr',parser:'binance'},{key:'kucoin',name:'KuCoin',url:'https://api.kucoin.com/api/v1/market/allTickers',parser:'kucoin'},{key:'bybit',name:'Bybit',url:'https://api.bybit.com/v5/market/tickers?category=spot',parser:'bybit'},{key:'dexscreener_eth',name:'DexScreener ETH',url:'https://api.dexscreener.com/latest/dex/search?q=ETH',parser:'dexscreener'},{key:'coingecko',name:'CoinGecko',url:'https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=100&page=1',parser:'coingecko'}];
const testnetExchangeDefs=[{key:'binance_test',name:'Binance Testnet',url:'https://testnet.binance.vision/api/v3/ticker/24hr',parser:'binance'},{key:'uniswap_sepolia',name:'Uniswap Sepolia',url:'https://api.thegraph.com/subgraphs/name/uniswap/uniswap-v3-sepolia',parser:'dexscreener'}];
function rebuildExchangeDefinitions(){exchangeDefs.forEach(d=>{State.exchanges[d.key]={name:d.name,status:'offline',pairs:[],url:d.url,parser:d.parser,auth:d.auth||false,wsStatus:'off'};});if(State.testnetsActive)testnetExchangeDefs.forEach(d=>{State.exchanges[d.key]={name:d.name,status:'offline',pairs:[],url:d.url,parser:d.parser,auth:d.auth||false,wsStatus:'off'};});}
async function loadApi(defKey){const ex=State.exchanges[defKey];const isCors=false;try{const r=await smartFetch(ex.url,{},isCors);if(!r.ok)throw new Error();const d=await r.json();let pairs=[];if(ex.parser==='okx')pairs=(d.data||[]).slice(0,300).map(t=>{const p=t.instId.split('-');if(p.length!==2)return null;const pr=parseFloat(t.last)||0;return{base:p[0],target:p[1],price:pr,volume:0,liquidity:pr*1e5,bidPrice:pr*0.999,askPrice:pr*1.001,exchange:defKey,exchangeType:'cex'};}).filter(Boolean);
else if(ex.parser==='binance')pairs=(Array.isArray(d)?d:[]).slice(0,400).map(t=>{const pr=parseFloat(t.lastPrice)||0;const ps=parsePairSymbol(t.symbol);if(!ps)return null;return{base:ps.base,target:ps.target,price:pr,volume:0,liquidity:pr*1e5,bidPrice:parseFloat(t.bidPrice)||pr*0.999,askPrice:parseFloat(t.askPrice)||pr*1.001,exchange:defKey,exchangeType:'cex'};}).filter(p=>p&&p.price>0);
else if(ex.parser==='dexscreener'){const raw=d?.pairs||[];pairs=raw.slice(0,300).map(p=>{const pr=parseFloat(p.priceUsd)||0,liq=p.liquidity?.usd||0;return{base:p.baseToken?.symbol||'?',target:p.quoteToken?.symbol||'ETH',price:pr,volume:p.volume?.h24||0,liquidity:liq,bidPrice:pr*0.997,askPrice:pr*1.003,exchange:defKey,exchangeType:'dex'};}).filter(p=>p.base!=='?'&&p.price>0);}
else if(ex.parser==='coingecko')pairs=(Array.isArray(d)?d:[]).slice(0,200).map(c=>({base:(c.symbol||'').toUpperCase(),target:'USD',price:c.current_price||0,volume:c.total_volume||0,liquidity:c.market_cap||0,bidPrice:(c.current_price||0)*0.999,askPrice:(c.current_price||0)*1.001,exchange:defKey,exchangeType:'info'}));
ex.pairs=pairs.filter(p=>p&&p.base&&p.target&&p.price>0);ex.status='online';log(`${ex.name}: ${pairs.length}p`,'success');}catch(e){ex.status='offline';ex.pairs=[];log(`${ex.name}: offline`,'error');}}
async function initSystem(){log('Initializing...');updateStatus('LOADING...');UI.updateProxyStatus();const start=performance.now();await Promise.allSettled(exchangeDefs.map(d=>loadApi(d.key)));if(State.testnetsActive)await Promise.allSettled(testnetExchangeDefs.map(d=>loadApi(d.key)));State.allPairs=Object.values(State.exchanges).flatMap(e=>e.pairs);State.userCoins.forEach(c=>{State.allPairs.push({base:c.symbol,target:c.quote||'USDT',price:c.price,volume:c.liq*0.3,liquidity:c.liq,bidPrice:c.price*0.95,askPrice:c.price*1.05,exchange:c.exchange||'QUANTM_DEX',exchangeType:'dex'});});State.stats.totalPairs=State.allPairs.length;State.computePurchasePower();updateIntraExCheckboxes();buildGraph();buildTriangles();displayLowValue();updateExchangeDisplay();updateStats();const on=Object.values(State.exchanges).filter(e=>e.status==='online').length;if(on>0){document.getElementById('scanBtn').disabled=false;updateStatus(`READY · ${on} online`);}else updateStatus('NO EXCHANGES ONLINE');State.operationLatency.push({op:'INIT',duration:Math.round(performance.now()-start)});UI.renderLatency();State.save();if(!Object.keys(State.forexRates).length&&State.selectedFiats.size)fetchForexRates();State.startAutoForex();if(document.getElementById('graphSlotContainer').style.display==='block'&&!State.graphRenderer)State.graphRenderer=new GraphRenderer('graphNetwork');UI.applyLevelConstraints();}
function buildGraph(){State.graph={};const pairs=getGraphPairs().map(applyWsCache);pairs.forEach(p=>{if(p.liquidity<50)return;if(!p.base||!p.target)return;if(!State.graph[p.base])State.graph[p.base]={};if(!State.graph[p.target])State.graph[p.target]={};const r1=p.bidPrice,r2=1/p.askPrice;if(r1>0)State.graph[p.base][p.target]={rate:r1,weight:-Math.log(r1),volume:p.volume,liquidity:p.liquidity,exchange:p.exchange,exchangeType:p.exchangeType};if(r2>0)State.graph[p.target][p.base]={rate:r2,weight:-Math.log(r2),volume:p.volume,liquidity:p.liquidity,exchange:p.exchange,exchangeType:p.exchangeType};});State.stats.graphNodes=Object.keys(State.graph).length;State.stats.graphEdges=Object.values(State.graph).reduce((s,o)=>s+Object.keys(o).length,0);}
function buildTriangles(){State.triangles=[];const ns=Object.keys(State.graph);const seen=new Set();for(let i=0;i<Math.min(ns.length,100);i++){const A=ns[i];const nA=Object.keys(State.graph[A]||{});for(const B of nA){const nB=Object.keys(State.graph[B]||{});for(const C of nB){if(State.graph[C]?.[A]){const canon=[A,B,C].sort().join('|');if(!seen.has(canon)){seen.add(canon);State.triangles.push([A,B,C]);}}}}}State.stats.triangleCount=State.triangles.length;}
function getGraphPairs(){const m=document.getElementById('arbMode').value;if(m==='intra')return[...State.selectedIntraExchanges].flatMap(k=>State.exchanges[k]?.pairs||[]);return Object.values(State.exchanges).filter(e=>e.status==='online'&&e.parser!=='coingecko').flatMap(e=>e.pairs);}
function applyWsCache(p){const c=State.wsTickers[p.exchange];if(c){const k=`${p.base}${p.target}`.toUpperCase();const t=c[k];if(t)return{...p,bidPrice:t.bid||p.bidPrice,askPrice:t.ask||p.askPrice};}return p;}
