async function runFullScan(){buildGraph();buildTriangles();State.opportunities={mega:[],triangular:[],bellman:[],suspicious:[]};const tri=scanTriangular();const bf=[];if(document.getElementById('bellmanToggle').checked&&State.level>=5){const targets=State.getTargetAssets();for(const t of targets)if(State.graph[t])bf.push(...bellmanFord(t,parseInt(document.getElementById('pathInput').value)));}const all=[...tri,...bf];all.forEach(o=>{if(o.profitPercent>5)State.opportunities.mega.push(o);else if(o.type==='triangular')State.opportunities.triangular.push(o);else State.opportunities.bellman.push(o);});updateStats();['megaOpps','triangularOpps','bellmanOpps'].forEach(id=>{document.getElementById(id).innerHTML='';});State.opportunities.mega.forEach(o=>UI.renderOpp(o,'megaOpps',true));State.opportunities.triangular.forEach(o=>UI.renderOpp(o,'triangularOpps'));State.opportunities.bellman.forEach(o=>UI.renderOpp(o,'bellmanOpps'));}
function scanTriangular(minP=0.0001){const opps=[];State.triangles.forEach(([A,B,C])=>{const orders=[[A,B,C,A]];for(const[s,m1,m2,e]of orders){const e1=State.graph[s]?.[m1],e2=State.graph[m1]?.[m2],e3=State.graph[m2]?.[e];if(!e1||!e2||!e3)continue;if(!State.validateCycle([e1,e2,e3]))continue;const inv=1000,fin=inv*e1.rate*e2.rate*e3.rate,profit=fin-inv,pct=(profit/inv)*100;if(pct>=minP&&pct<50){const ms=Math.min(e1.liquidity,e2.liquidity,e3.liquidity)*0.05;opps.push({type:'triangular',path:[s,m1,m2,e],profitPercent:pct,actualProfit:toUsd((ms/inv)*profit,s),maxTradeSize:toUsd(ms,s),edges:[e1,e2,e3]});}}});return opps;}
function bellmanFord(start,depth=5){const opps=[];const target=State.getTargetAssets();if(!target.includes(start))return opps;const cs=Object.keys(State.graph);const dist={},pred={};cs.forEach(c=>{dist[c]=Infinity;pred[c]=null;});dist[start]=0;for(let i=0;i<depth;i++){let upd=false;for(const u of cs){const nb=State.graph[u];if(!nb)continue;for(const v in nb){const w=nb[v].weight;if(dist[u]!==Infinity&&dist[u]+w<dist[v]){dist[v]=dist[u]+w;pred[v]=u;upd=true;}}}if(!upd)break;}for(const v in pred){if(pred[v]&&dist[v]!==Infinity){let cur=v,cycle=[],vis=new Set();while(cur&&!vis.has(cur)){vis.add(cur);cycle.unshift(cur);cur=pred[cur];}if(cycle[0]===start&&cycle.length>=2){let amt=1000,edges=[];for(let i=0;i<cycle.length-1;i++){const e=State.graph[cycle[i]]?.[cycle[i+1]];if(!e)break;amt*=e.rate;edges.push(e);}const le=State.graph[cycle[cycle.length-1]]?.[cycle[0]];if(le){amt*=le.rate;edges.push(le);const pc=(amt-1000)/10;if(pc>=0.0001&&pc<50){const ms=Math.min(...edges.map(e=>e.liquidity))*0.05;opps.push({type:'bellman-ford',path:[...cycle,start],profitPercent:pc,actualProfit:toUsd((ms/1000)*(amt-1000),start),maxTradeSize:toUsd(ms,start),edges});}}}}}return opps;}
function toUsd(amt,asset){const price=State.getAssetPrice(asset);return price>0?amt*price:amt;}

